<?php

declare(strict_types=1);

namespace App\Api\Supervision;

use App\Api\Contracts\Domains\ApiSender;
use App\Asks\Data\AskCard;
use App\Asks\Data\AskInbox;
use App\Support\CallKey;

/**
 * The API of Supervision, generated by php artisan journal:api; run it again instead of editing.
 */
final readonly class SupervisionApi
{
    public function __construct(private ApiSender $sender) {}

    public function listAsks(
        string|null $before = null,
    ): AskInbox {
        return $this->sender->send(ListAsksPayload::from([
            'before' => $before,
        ]));
    }

    public function makeAsk(
        CallKey $requestKey,
        string $body,
        string|null $type = null,
    ): AskCard {
        return $this->sender->send(MakeAskPayload::from([
            'requestKey' => $requestKey,
            'body' => $body,
            'type' => $type,
        ]));
    }

    public function replyToAsk(
        CallKey $requestKey,
        string $id,
        string $body,
    ): AskCard {
        return $this->sender->send(ReplyToAskPayload::from([
            'requestKey' => $requestKey,
            'id' => $id,
            'body' => $body,
        ]));
    }

    public function showAsk(
        string $id,
    ): AskCard {
        return $this->sender->send(ShowAskPayload::from([
            'id' => $id,
        ]));
    }

    public function withdrawAsk(
        CallKey $requestKey,
        string $id,
    ): AskCard {
        return $this->sender->send(WithdrawAskPayload::from([
            'requestKey' => $requestKey,
            'id' => $id,
        ]));
    }
}
